import{z as n,x as B,o as t,c as d,q as i,j as o,D as e,d as l,s as r,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"刻蚀模型校准","description":"","frontmatter":{"title":"刻蚀模型校准","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/etch-model-calibration.md","filePath":"litho/etch-model-calibration.md","lastUpdated":1791413859000}'),p={name:"litho/etch-model-calibration.md"};function h(D,a,c,m,I,C){const A=B("Mermaid");return t(),d("div",null,[a[2]||(a[2]=i('<h1 id="刻蚀模型校准" tabindex="-1">刻蚀模型校准 <a class="header-anchor" href="#刻蚀模型校准" aria-label="Permalink to &quot;刻蚀模型校准&quot;">​</a></h1><div class="epigraph"><p>ADI 贴目标不等于硅上贴目标；刻蚀核要在 AEI 上单独拟合，换腔体就换版本。</p><footer>—— 对照紧凑刻蚀模型、ADI/AEI 成对计量与负载效应的产线通称</footer></div><p><a href="/litho/3d-resist-model">上一课</a>承认胶是三维的。缺口是下一跳：等离子体把胶形变成硬掩模/介质/硅形，偏置随密度与深宽比变。本课钉刻蚀模型校准。<a href="/litho/etch-in-opc">刻蚀进 OPC</a> 已说明为何要进迭代；这里补怎么标定。全芯片算力，留给<a href="/litho/full-chip-simulation-cost">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>紧凑刻蚀模型吃显影多边形，吐刻蚀后边：短程偏置 + 密度核 + 有时取向。校准数据必须是<strong>同一部位</strong>的 ADI 与 AEI，否则光学残差会被刻蚀项吞掉。ARDE、微负载、大面积负载尺度不同，一个核半径不够——与 PEC 多层核同构。</p><p><span class="marginnote">为什么重要：校准数据必须是同一部位的成对 ADI/AEI。若 ADI 采自甲片、AEI 采自乙片，光学残差会被刻蚀项「吞掉」，拟出一个当场看似很准、换一片布局就翻车的核。</span></p><p>缺口是<strong>AEI 协议</strong>，不是再讲 RIE 化学。把「经验 etch bias 表」当校准完成，二维邻域仍会在 SRAM–逻辑边界爆。</p><h3 id="换配方即新模型" tabindex="-1">换配方即新模型 <a class="header-anchor" href="#换配方即新模型" aria-label="Permalink to &quot;换配方即新模型&quot;">​</a></h3><p>功率、气体、过刻、硬掩模材料一变，核作废。OPC 版本号要含刻蚀工艺 id。APC 以后可以微调平均偏置，但不能当全核重标定。</p><p><span class="marginnote">直觉类比：刻蚀核像「某个灶台加某口锅」的火候曲线；换气体、换功率、换硬掩模等于换灶换锅，老火候整体作废。APC 调平均偏置只是「微调火苗」，改不了菜谱本身。</span></p><p><span class="marginnote">最终签核写清轮廓：ADI、AEI 还是电学。PW-band 只含 ADI 时，窗口角可能在转印里被吃掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验：密度矩阵、通过节距、二维、深宽比变化（不同开口）。计量：CD-SEM AEI、有时 TEM 截面。拟合：与胶分两阶段，先锁 ADI 再锁刻蚀。保持集含产品 clips。与 <a href="/litho/etch-bias-opc-loop">etch bias OPC 回环</a> 后课（集成门）的关系：本课是模型； fab 回环是用在线 AEI 去更新偏置——控制层，不是再建一个物理腔。</p>',13)),(t(),o(s,null,{default:e(()=>[r(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAL%5B%22%E6%A0%A1%E5%87%86%E7%89%87%EF%BC%9A%E5%BC%80%E5%8F%A3%E7%8E%87%C3%97%E8%8A%82%E8%B7%9D%C3%97%E5%8F%96%E5%90%91%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20MET%5B%22%E6%88%90%E5%AF%B9%20ADI%2FAEI%20%E8%AE%A1%E9%87%8F%22%5D%0A%20%20MET%20--%3E%20P1%5B%22%E9%98%B6%E6%AE%B5%E4%B8%80%EF%BC%9A%E9%94%81%E8%83%B6%EF%BC%8C%E5%A4%8D%E7%8E%B0%20ADI%22%5D%0A%20%20P1%20--%3E%20P2%5B%22%E9%98%B6%E6%AE%B5%E4%BA%8C%EF%BC%9A%E6%8B%9F%E5%90%88%E5%88%BB%E8%9A%80%E6%A0%B8%22%5D%0A%20%20P2%20--%3E%20HOLD%5B%22%E4%BF%9D%E6%8C%81%E9%9B%86%E4%BA%A7%E5%93%81%20clip%20%E6%A3%80%E9%AA%8C%22%5D%0A%20%20HOLD%20--%3E%20OK%7B%22%E4%BF%9D%E6%8C%81%E9%9B%86%E8%AF%AF%E5%B7%AE%E8%BE%BE%E6%A0%87%22%7D%0A%20%20OK%20--%20%22%E5%90%A6%22%20--%3E%20CAL%0A%20%20OK%20--%20%22%E6%98%AF%22%20--%3E%20REL%5B%22%E5%8F%91%E5%B8%83%E5%B8%A6%E5%B7%A5%E8%89%BA%20id%20%E7%9A%84%E6%A0%B8%E7%89%88%E6%9C%AC%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"数字实例：一张典型校准片会用若干档开口率（例如 \\(10\\%\\)、\\(30\\%\\)、\\(50\\%\\)、\\(70\\%\\)）乘以多组节距和两种取向铺满矩阵；再留一批产品 clip 不参与拟合当「保持集」——拟合误差小不算数，没见过的图形误差也小，核才敢发布。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"中性基消耗随开口面积变（负载），离子角分布随深宽比变（ARDE），聚合物在侧壁沉积随局部通量变。紧凑核是这些效应在边法向上的投影，不是 PIC 粒子模拟。梯度若要穿过核，核必须对 jog 足够光滑，否则 OPC 振荡。",-1)),(t(),o(s,null,{default:e(()=>[r(A,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADI%5B%22%E6%98%BE%E5%BD%B1%E8%BE%B9%22%5D%20--%3E%20KERNEL%5B%22%E5%AF%86%E5%BA%A6%20%2B%20%E7%9F%AD%E7%A8%8B%E5%88%BB%E8%9A%80%E6%A0%B8%22%5D%0A%20%20KERNEL%20--%3E%20AEI%5B%22%E5%88%BB%E8%9A%80%E5%90%8E%E8%BE%B9%22%5D%0A%20%20PAIR%5B%22%E6%88%90%E5%AF%B9%20ADI%2FAEI%20%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20FIT%5B%22%E6%8B%9F%E5%90%88%E6%A0%B8%22%5D%0A%20%20FIT%20--%3E%20KERNEL%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>紧凑刻蚀 ≠ 等离子体第一性原理。不把某腔体的 nm/min 写成宇宙速率。校准不覆盖等离子体不稳定与颗粒。</p><p>后课默认：前向链光学–胶–刻蚀都有可调用核；下一课问全芯片扫一遍要多少算力，从而 LRC 只能抽样。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>刻蚀核在成对 ADI/AEI 上单独拟合，与胶项分家。</li><li>负载多层尺度；换腔体换版本。</li><li>签核轮廓定义必须写进模型合同。</li><li>出处：紧凑刻蚀模型与负荷效应产线通称；计算光刻 OPC–刻蚀链。</li></ul>',5))])}const P=n(p,[["render",h]]);export{u as __pageData,P as default};
